INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱全昱", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“朱温在即位前更名晃”中为质问者。", "biography": null, "status": "draft", "id": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "唐昭宣帝", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为遣使者。", "biography": null, "status": "draft", "id": "b6981468-b3da-5cb4-ac72-9dfe618cdcd5"}, {"name": "朱诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "朱温、朱全昱、朱存之父，以《五经》教授乡里。", "biography": "朱温、朱全昱、朱存之父，以《五经》教授乡里。", "status": "draft", "id": "e27f812b-f91f-544d-9e6d-b6a3076c8ed8"}, {"name": "王氏（朱温母）", "aliases": ["文惠王皇后"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "朱温之母，姓王氏；丈夫去世后携子寄居萧县刘崇家。", "biography": "朱温之母，姓王氏；丈夫去世后携子寄居萧县刘崇家。", "status": "draft", "id": "2cc6ea51-f5b6-5f59-b130-1ed2810802cd"}, {"name": "朱友文", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“朱友文出任开封尹并主持建昌院”中为受命者。", "biography": null, "status": "draft", "id": "28293c54-1774-5e6d-b0a7-6ab233fcd5ec"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱温在即位前更名晃", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月壬戌", "dynasty": "唐末五代十国", "description": "梁王在即位前更名晃；原文并记其兄朱全昱对称帝提出质问。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "9fa88b8f-8d2e-5e3a-b35b-15808df5a632"}, {"title": "朱温称帝，后梁建立", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年／梁开平元年四月甲子即位、戊辰改元国号", "dynasty": "后梁", "description": "朱温在大梁即皇帝位，随后改元开平，国号大梁；唐昭宣帝被降为济阴王。汴州升为开封府、号东都。后梁建立并未使各地割据政权随之消失。", "phases": [], "location_name": "大梁（金祥殿）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "1047bb1e-a052-5199-9709-9bede79f6af2"}, {"title": "后梁将济阴王迁往曹州并派兵看守", "start_year": 907, "end_year": 907, "time_original": "907年四月戊辰后；确日未载", "dynasty": "唐", "description": "后梁将济阴王迁往曹州并派兵看守。", "phases": [], "location_name": "曹州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cb8de7b2-1767-5c4c-b138-d30e081d9bfa"}, {"title": "后梁改汴州为开封府并调整京府军名", "start_year": 907, "end_year": 907, "time_original": "907年四月戊辰后诏令；确日未载", "dynasty": "唐", "description": "后梁改汴州为开封府并调整京府军名。", "phases": [], "location_name": "汴州、京兆府、魏博", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bb64015c-4fb2-51d7-aa16-c5ef603216a9"}, {"title": "后梁封马殷为楚王", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月辛未", "dynasty": "唐末五代十国", "description": "后梁以武安节度使马殷为楚王。封号不等于后梁实际直接控制其辖地。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "8cf57a60-57f4-577f-bbdc-951e4aafe44d"}, {"title": "敬翔主持崇政院，枢密院职事并入", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月至五月甲午", "dynasty": "唐末五代十国", "description": "敬翔先知崇政院事，负责承宣旨意及顾问谋议；五月后梁废枢密院，职事并入崇政院，以敬翔为院使。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "dcb44f0b-d6c9-58ab-aae0-0ae44f0d4d55"}, {"title": "朱温追尊先祖及父母", "start_year": 907, "end_year": 907, "time_original": "907年（追尊及相关礼仪分阶段记载，各书系月有异）", "dynasty": "唐末五代十国", "description": "朱温追尊高祖以来的先人，尊父朱诚为烈祖文穆皇帝，母王氏为文惠皇后。追尊发生于先人去世之后。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "41008971-04ea-5e8f-8bd0-2aa02eabcdde"}, {"title": "朱友文出任开封尹并主持建昌院", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月至五月辛卯", "dynasty": "唐末五代十国", "description": "朱温以养子朱友文为开封尹、判建昌院事，掌财政事务。五月建昌院改为建昌宫，相关职名随之改为建昌宫使。", "phases": [], "location_name": "开封", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "044e351e-d4e5-5811-96a8-601d833751e9"}, {"title": "后梁削夺李克用官爵", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月乙亥", "dynasty": "唐末五代十国", "description": "后梁下制削夺李克用官爵。原文同时记河东等地仍用唐年号，显示各地对后梁正朔的接受并不一致。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "5a40eb5a-534e-5998-a47b-5c771992120f"}, {"title": "蜀王与晋王讨论讨梁及称帝", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后条，具体日期未载", "dynasty": "唐末五代十国", "description": "蜀王致书晋王，提出各帝一方、平梁后再立唐宗室；李克用回书不许。此为书信提议，不能据此认定双方已结成军事同盟。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "6782cad6-c288-5916-963c-dba6b6c72440"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "兄长", "description": "朱全昱为朱温兄长；见907年改名与封王记载。", "status": "draft", "id": "25262d71-7aa3-5bf2-b9a6-8a7a408ffca4", "person_a": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5", "person_b": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"relation_type": "父亲", "description": "朱诚为朱温之父。", "status": "draft", "id": "d09307b2-c689-52fd-a70a-e63e9b86a3e0", "person_a": "e27f812b-f91f-544d-9e6d-b6a3076c8ed8", "person_b": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"relation_type": "母亲", "description": "王氏为朱温之母，史书称文惠王皇后。", "status": "draft", "id": "24768220-271f-57f0-a400-4133d7992596", "person_a": "2cc6ea51-f5b6-5f59-b130-1ed2810802cd", "person_b": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"relation_type": "养父", "description": "朱温为朱友文养父；原文明确称养子，并说友文本康氏之子。907年受任及封王不改变养子属性。", "status": "draft", "id": "98103dc6-92bb-5e22-b001-4716a86a09d6", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "28293c54-1774-5e6d-b0a7-6ab233fcd5ec"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

