SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "梁王朱温更名晃。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p016·原文件第21行", "note": "原文：壬戌，梁王更名晃。；核对说明：朱温、朱晃为同一人，复用旧907更名事件及既有人物，不另立人物。", "status": "draft", "id": "fbaf24cd-9b6f-5519-aa12-dcadd7e901b7", "subject_id": "9fa88b8f-8d2e-5e3a-b35b-15808df5a632", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年四月壬戌", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p016·原文件第21行", "note": "原文：壬戌，梁王更名晃。；核对说明：朱温、朱晃为同一人，复用旧907更名事件及既有人物，不另立人物。", "status": "draft", "id": "53cc6f32-9896-5da9-a960-e331075838ad", "subject_id": "9fa88b8f-8d2e-5e3a-b35b-15808df5a632", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "event", "field_path": "description", "claim_text": "朱全昱在朱温即位前质问其称帝。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p016·原文件第21行", "note": "原文：王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明：朱全昱的话是其反对称帝的言辞；“王兄”明示长幼。", "status": "draft", "id": "e2ad7d09-f90a-5d75-aad1-361bbbb4b8dc", "subject_id": "9fa88b8f-8d2e-5e3a-b35b-15808df5a632", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱全昱：兄弟关系与朱温更名记载中的人物。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p016·原文件第21行", "note": "原文：王兄全昱闻王将即帝位；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "2028d6a0-a52a-5f70-bd38-28fc01ecb964", "subject_id": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱温：兄弟关系与朱温更名记载中的人物。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p016·原文件第21行", "note": "原文：王兄全昱闻王将即帝位；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "1d7cf630-8d18-5a43-8a61-d831c821b876", "subject_id": "0555e455-34d4-54ef-b93e-b0e6425018ab", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "朱全昱为朱温兄长；见907年改名与封王记载。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p016·原文件第21行", "note": "原文：王兄全昱闻王将即帝位；核对说明：原文“王兄”明示朱全昱为朱温兄长；复用已有方向。", "status": "draft", "id": "e30bcd10-463d-52cf-987e-a53f0a87defa", "subject_id": "25262d71-7aa3-5bf2-b9a6-8a7a408ffca4", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "event", "field_path": "description", "claim_text": "朱温即皇帝位。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。；核对说明：“兗冕”为本电子底本文字，旧书作“袞冕”，不静默改字；复用后梁建立事件。", "status": "draft", "id": "4e7da5b1-a7de-53a9-aeeb-38746d99246d", "subject_id": "1047bb1e-a052-5199-9709-9bede79f6af2", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年四月甲子即帝位；戊辰改元国号", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。；核对说明：“兗冕”为本电子底本文字，旧书作“袞冕”，不静默改字；复用后梁建立事件。", "status": "draft", "id": "e96cabdd-5ff7-5f98-9421-36596c96063f", "subject_id": "1047bb1e-a052-5199-9709-9bede79f6af2", "source_id": "e01530ae-e153-5045-ade3-3974ab03c077"}, {"subject_table": "event", "field_path": "description", "claim_text": "戊辰大赦、改元开平，定国号大梁。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：戊辰，大赦，改元，国号大梁。；核对说明：即位与改元相隔数日；不将戊辰写作即位日。", "status": "draft", "id": "97cce1e3-7c12-5b9c-8b66-daa53cc6ec78", "subject_id": "1047bb1e-a052-5199-9709-9bede79f6af2", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "event", "field_path": "description", "claim_text": "奉唐昭宣帝为济阴王。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。；核对说明：唐昭宣帝封济阴王；迁曹州及守卫见本段后句。", "status": "draft", "id": "9296cba7-2145-50ee-b0ad-7e3d2052fe22", "subject_id": "1047bb1e-a052-5199-9709-9bede79f6af2", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁将济阴王迁往曹州并派兵看守。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：此人即退位后封济阴王的唐昭宣帝；本句没有记其死亡。", "status": "draft", "id": "2270d449-c007-5ec3-a2da-375a467fee2f", "subject_id": "cb8de7b2-1767-5c4c-b138-d30e081d9bfa", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年四月戊辰后；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：此人即退位后封济阴王的唐昭宣帝；本句没有记其死亡。", "status": "draft", "id": "b7a9519d-cc34-56bf-983b-df779686a666", "subject_id": "cb8de7b2-1767-5c4c-b138-d30e081d9bfa", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记唐昭宣帝：被迁并受看守者。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "9b521dbb-1dca-59c4-bab9-1340ed52fab0", "subject_id": "b6981468-b3da-5cb4-ac72-9dfe618cdcd5", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宣帝：被迁并受看守者。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "82b8da19-51d1-5848-ad97-9f90ee231dd4", "subject_id": "2b413fe7-e58a-54b1-ad05-4a2fc5d7af5d", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁改汴州为开封府并调整京府军名。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。；核对说明：按主书记录制度与名号改变；不据名称直接绘制疆域边界。", "status": "draft", "id": "0760495c-3c77-55cf-a113-3e681122862f", "subject_id": "bb64015c-4fb2-51d7-aa16-c5ef603216a9", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年四月戊辰后诏令；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。；核对说明：按主书记录制度与名号改变；不据名称直接绘制疆域边界。", "status": "draft", "id": "276cbbdf-3b4f-5a09-8e39-8912daa92eeb", "subject_id": "bb64015c-4fb2-51d7-aa16-c5ef603216a9", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温：改制的后梁皇帝。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p017·原文件第22行", "note": "原文：以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "1f67a1de-0e6d-5c0a-954f-11142cd94938", "subject_id": "6352b806-5299-53cb-8461-aae4333a8294", "source_id": "615753b7-ac04-59c6-97f1-41598c039cdb"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷三保存诏文，直书改天祐四年为开平元年、国号大梁。", "citation": "《旧五代史》卷三，段落 jiu-wudaishi-205deb4a7860-p000259；EPUB电子本，纸本及异文待核", "note": "原文：可改唐天祐四年為開平元年，國號大樑。；核对说明：诏文是政权自述的文书证据；只独立证明诏令内容，不证明“受命于天”等修辞。", "status": "draft", "id": "81f91f03-3edd-55bf-abe1-07b586816f6a", "subject_id": "1047bb1e-a052-5199-9709-9bede79f6af2", "source_id": "d8211f8b-a360-5a55-a669-616a66144f1a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷三诏文记升汴州为开封府并建名东都。", "citation": "《旧五代史》卷三，段落 jiu-wudaishi-205deb4a7860-p000259；EPUB电子本，纸本及异文待核", "note": "原文：宜升汴州為開封府，建名東都。；核对说明：诏文未涵盖主书本事件其余所有京府、军名变更；只印证开封府与东都两项。", "status": "draft", "id": "cc6ac10f-33eb-5c3b-9c18-cddf5de1ad49", "subject_id": "bb64015c-4fb2-51d7-aa16-c5ef603216a9", "source_id": "d8211f8b-a360-5a55-a669-616a66144f1a"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁封马殷为楚王。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p018·原文件第23行", "note": "原文：辛未，以武安节度使马殷为楚王。；核对说明：封王是名号授予，不据此推定后梁直接控制湖南。", "status": "draft", "id": "dbf7ea28-3ff3-5976-8ad9-588963871eff", "subject_id": "8cf57a60-57f4-577f-bbdc-951e4aafe44d", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年四月辛未", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p018·原文件第23行", "note": "原文：辛未，以武安节度使马殷为楚王。；核对说明：封王是名号授予，不据此推定后梁直接控制湖南。", "status": "draft", "id": "42e9b732-e53b-5129-9ca2-9e41917d566b", "subject_id": "8cf57a60-57f4-577f-bbdc-951e4aafe44d", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "敬翔知崇政院事。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p019·原文件第24行", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。；核对说明：本段记“知崇政院事”；枢密院职事并入发生在后续五月段落，不倒填。", "status": "draft", "id": "b3476052-1469-5a11-9741-7340c030aa32", "subject_id": "dcb44f0b-d6c9-58ab-aae0-0ae44f0d4d55", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年四月辛未后；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p019·原文件第24行", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。；核对说明：本段记“知崇政院事”；枢密院职事并入发生在后续五月段落，不倒填。", "status": "draft", "id": "4351c434-70ac-59ce-b173-cf11829bf2d2", "subject_id": "dcb44f0b-d6c9-58ab-aae0-0ae44f0d4d55", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "主书称敬翔参与军谋、民政，并在禅代之际有较多谋划。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p019·原文件第24行", "note": "原文：翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。；核对说明：“三十余年”为主书概数，且是回顾性评述，不推成907年新任职年限。", "status": "draft", "id": "76627db2-13dd-5a1d-a3c7-5c2644a0d42f", "subject_id": "dcb44f0b-d6c9-58ab-aae0-0ae44f0d4d55", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "朱温追尊先祖及父母。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p020·原文件第25行", "note": "原文：追尊皇高祖考、妣以来皆为帝、后，皇考诚为烈祖文穆皇帝。妣王氏为文惠皇后。；核对说明：“追尊”是身后尊号，不推成朱诚或王氏在907年仍在世。", "status": "draft", "id": "6cddd580-280f-5044-